/* Solo effects of original abilities granted by equipment/card scripts. */
static void item_status52(Combat*g,CombatMob*m,int effect,float seconds);
static float combat_walk_speed(const Combat*g);
static void class_gear_ailment52(Combat*g,CombatMob*m,unsigned id,int rank){if(combat_status_boss(m))return;float duration=class_duration50(id,rank,1);if(duration<=0)duration=30;switch(id){case SKG52_NPC_CRITICALWOUND:m->class50.criticalWoundUntil52=g->time+duration;m->class50.criticalWoundRank52=rank;break;case SKG52_NPC_DRAGONFEAR:{int effects[4]={2,6,7,9};int n=combat_random(g)%4;item_status52(g,m,effects[n],duration);break;}case SKG52_NPC_WIDEBLEEDING:m->class50.bleedUntil=g->time+duration;m->class50.bleedNext=g->time+10;break;case SKG52_NPC_HELLJUDGEMENT:case SKG52_NPC_WIDECURSE:m->class50.curseUntil52=g->time+duration;break;case SKG52_NPC_WIDECONFUSE:m->class50.confuseUntil=g->time+duration;break;case SKG52_NPC_WIDESILENCE:m->class50.silenceUntil=g->time+duration;break;case SKG52_GM_SANDMAN:m->class50.sleepUntil=g->time+duration;break;case SKG52_NPC_SLOWCAST:m->class50.slowCastUntil52=g->time+duration;m->class50.slowCastRank52=rank;if(m->castUntil48>g->time)m->castUntil48=g->time+(m->castUntil48-g->time)*(100+20*rank)/100;break;}}
static void class_gear_execute52(Combat*g,unsigned id,int rank,int target,float x,float y){
 if(id==SKG52_ALL_CATCRY){combat_message(g,"Meow.");return;}
 if(id==SKG52_TK_RUN){int i=id-127;if(class_active50(g,id)){if(rank>=7&&inventory_wtype46(g)==0&&g->time-g->class50.next[i]<=1)g->class50.spurtUntil60=g->time+class_duration50(id,rank,1);g->class50.until[i]=0;}else{g->class50.level[i]=rank;g->class50.until[i]=g->time+86400;g->class50.next[i]=g->time;g->class50.runFaceX52=g->faceX;g->class50.runFaceY52=g->faceY;g->autoAttack=0;}return;}
 if(id==SKG52_TK_HIGHJUMP){float dx=g->faceX,dy=g->faceY,len=sqrtf(dx*dx+dy*dy);if(len<.001f){dx=0;dy=1;len=1;}float nx=g->x+dx/len*rank*16,ny=g->y+dy/len*rank*16;int occupied=0;for(unsigned i=0;i<MOB_COUNT;i++)if(g->mobs[i].enabled&&g->mobs[i].hp>0&&fabsf(g->mobs[i].x-nx)<4&&fabsf(g->mobs[i].y-ny)<4)occupied=1;if(!occupied&&(!g->canMove||g->canMove(g->world,nx,ny,nx,ny))){g->x=nx;g->y=ny;g->autoAttack=0;g->target=-1;}return;}
 if(id==SKG52_NPC_MAGICMIRROR||id==SKG52_NPC_STONESKIN||id==SKG52_NPC_ANTIMAGIC){if(id==SKG52_NPC_STONESKIN)g->class50.until[SKG52_NPC_ANTIMAGIC-127]=0;if(id==SKG52_NPC_ANTIMAGIC)g->class50.until[SKG52_NPC_STONESKIN-127]=0;class_buff50(g,id,rank);stat_refresh(g);return;}
 if(id==SKG52_NPC_EARTHQUAKE){int slot=class_area_slot50(g);if(slot>=0)g->areas50[slot]=(ClassArea50){.id=id,.rank=rank,.map=g->mapId,.x=g->x,.y=g->y,.until=g->time+.9f,.next=g->time,.created=g->time};return;}
 if(id==SKG52_NPC_DARKSTRIKE&&target>=0){CombatMob*m=g->mobs+target;const ClassSkill50*d=class_skill_data50(id);int hits=d->hits[rank-1];if(hits<0)hits=-hits;if(hits<1)hits=1;int damage=combat_magic_def52(g,m,combat_magic_power48(g)*hits,hits);damage=damage*class_attack_rate48(g,m,7)/100;skill_hit_ex(g,target,damage,1,hits);return;}
 if(id==SKG52_ITM_TOMAHAWK||id==SKG52_NPC_CRITICALWOUND||id==SKG52_GM_SANDMAN){if(target<0)return;CombatMob*m=g->mobs+target;if(id!=SKG52_GM_SANDMAN)skill_hit(g,target,class_physical50(g,m,100,0,-1),0);class_gear_ailment52(g,m,id,rank);return;}
 const ClassSkill50*d=class_skill_data50(id);float radius=(d?d->splash[rank-1]:0)*8+4;for(unsigned i=0;i<MOB_COUNT;i++){CombatMob*m=g->mobs+i;if(!class_in_area50(g,m,g->x,g->y,radius))continue;if(id==SKG52_NPC_WIDESOULDRAIN){if(!m->class50.initialized){m->class50.sp=mobClassData50[m->kind][2];m->class50.initialized=1;}m->class50.sp-=mobClassData50[m->kind][2]*(((rank-1)%5+1)*20)/100;if(m->class50.sp<0)m->class50.sp=0;continue;}
  if(id==SKG52_NPC_VAMPIRE_GIFT||id==SKG52_NPC_PULSESTRIKE||id==SKG52_NPC_HELLJUDGEMENT){int hp=m->hp,ratio=id==SKG52_NPC_VAMPIRE_GIFT?100+((rank-1)%5+1)*100:100*rank;skill_hit(g,i,class_physical50(g,m,ratio,0,-1),0);if(id==SKG52_NPC_VAMPIRE_GIFT){g->hp+=hp-m->hp;if(g->hp>g->maxhp)g->hp=g->maxhp;}if(id==SKG52_NPC_PULSESTRIKE)combat_knockback(g,i,m->x-g->x,m->y-g->y,d->knockback[rank-1]*8);}
  class_gear_ailment52(g,m,id,rank);
 }
}
static void class_gear_tick52(Combat*g,float dt){int changed=0;unsigned buffs[3]={SKG52_NPC_MAGICMIRROR,SKG52_NPC_STONESKIN,SKG52_NPC_ANTIMAGIC};for(unsigned n=0;n<3;n++){float*t=g->class50.until+buffs[n]-127;if(*t>0&&*t<=g->time){*t=0;changed=1;}}if(changed)stat_refresh(g);if(class_active50(g,SKG52_TK_RUN)){int slot=SKG52_TK_RUN-127;if(g->hp<=0||g->hitStun>0||g->sitting||g->hideLeft>0||g->class50.rootUntil>g->time||g->autoAttack||combat_casting(g)||(g->lastCast>g->class50.next[slot]&&g->fxSkill!=SKG52_TK_RUN))g->class50.until[slot]=0;else{float step=combat_walk_speed(g)*dt,x=g->x,y=g->y;int moved=combat_move(g,&g->x,&g->y,x+g->class50.runFaceX52*step,y+g->class50.runFaceY52*step);if(!moved)g->class50.until[slot]=0;else g->moving=1;}}
 for(unsigned i=0;i<CLASS_AREAS50;i++){ClassArea50*a=g->areas50+i;if(a->id!=SKG52_NPC_EARTHQUAKE||a->map!=g->mapId||a->until<=g->time||a->next>g->time||a->hits>=3)continue;a->next+=.3f;a->hits++;float radius=class_skill_data50(a->id)->splash[a->rank-1]*8+4;int count=0;for(unsigned n=0;n<MOB_COUNT;n++)count+=class_in_area50(g,g->mobs+n,a->x,a->y,radius);int old=g->fxSkill;g->fxSkill=a->id;if(count)for(unsigned n=0;n<MOB_COUNT;n++){CombatMob*m=g->mobs+n;if(class_in_area50(g,m,a->x,a->y,radius))skill_hit_now49(g,n,class_physical50(g,m,200+100*a->rank+100*(a->rank/2),1,0)/count,1,1);}g->fxSkill=old;}
}
